# For each 3, check if any 8 is within Manhattan distance 1 (i.e., adjacent including diagonals)
for r in range(n):
    for c in range(m):
        if output_grid[r][c] == 3:
            # Check 8-way neighbors
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if (nr, nc) in positions_8:
                        output_grid[r][c] = 8
                        break
                if (r, c) in positions_8:
                    break
            # Actually the check above is wrong, let me redo
            is_adjacent_to_8 = False
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m and input_grid[nr][nc] == 8:
                        is_adjacent_to_8 = True
                        break
                if is_adjacent_to_8:
                    break
            if is_adjacent_to_8:
                output_grid[r][c] = 8

changed = 0
for r in range(n):
    for c in range(m):
        if output_grid[r][c] != input_grid[r][c]:
            changed += 1

print(f"8-way adjacent 3s changed: {changed}")
print("\nOutput rows 10-15:")
for r in range(10, 16):
    print(output_grid[r])

